function refreshLayerList(){const list=$('#layerStack');list.replaceChildren();[...layerItems].reverse().forEach(item=>{const row=document.createElement('div');row.className='layer-row'+(item===activeLayerItem?' selected':'');const pick=document.createElement('button');pick.textContent=item.label;pick.onclick=()=>{activeLayerItem=item;$('#posterStage').querySelectorAll('.canvas-selected,.text-selected').forEach(x=>x.classList.remove('canvas-selected','text-selected'));item.el.classList.add('canvas-selected');if(sceneKeys.includes(item.kind))selectCanvasLayer(item.kind);else selectedCanvasText=item.kind==='group'?item.el.querySelector('em,h2,p'):item.el;refreshLayerList()};const eye=document.createElement('button');eye.textContent=item.hidden?'숨김':'표시';eye.setAttribute('aria-label',item.label+' 표시 전환');eye.onclick=()=>{item.hidden=!item.hidden;item.el.style.visibility=item.hidden?'hidden':'';refreshLayerList()};const up=document.createElement('button');up.textContent='↑';up.setAttribute('aria-label',item.label+' 앞으로');up.onclick=()=>{const i=layerItems.indexOf(item);if(i<layerItems.length-1){[layerItems[i],layerItems[i+1]]=[layerItems[i+1],layerItems[i]];applyLayerOrder()}};const down=document.createElement('button');down.textContent='↓';down.setAttribute('aria-label',item.label+' 뒤로');down.onclick=()=>{const i=layerItems.indexOf(item);if(i>0){[layerItems[i],layerItems[i-1]]=[layerItems[i-1],layerItems[i]];applyLayerOrder()}};row.append(pick,eye,up,down);list.append(row)})}
