$('#addCanvasText').onclick=()=>newCanvasObject('text');$('#addCanvasStar').onclick=()=>newCanvasObject('star');$('#addCanvasImage').onclick=()=>$('#layerImageUpload').click();$('#layerImageUpload').onchange=e=>{const f=e.target.files[0];if(f&&['image/png','image/jpeg','image/webp'].includes(f.type)&&f.size<=10*1024*1024)newCanvasObject('image',URL.createObjectURL(f));else if(f)toast('10MB 이하 PNG, JPG, WEBP 이미지를 선택해 주세요.');e.target.value=''};
const oldCanvasDelete=canvasDelete.onclick;canvasDelete.onclick=()=>{if(selectedCanvasText?.classList.contains('user-canvas-object')){const i=layerItems.findIndex(x=>x.el===selectedCanvasText);selectedCanvasText.remove();if(i>=0)layerItems.splice(i,1);selectedCanvasText=null;activeLayerItem=null;refreshLayerList()}else oldCanvasDelete()};
