['canvasSmaller','canvasLarger','canvasRotateLeft','canvasRotateRight'].forEach(id=>{const button=$('#'+id),original=button.onclick;button.onclick=()=>{const el=selectedCanvasText;if(!el?.classList.contains('user-canvas-object'))return original();let scale=+(el.dataset.scale||1),rotation=+(el.dataset.rotation||0);if(id==='canvasSmaller')scale=Math.max(.2,scale-.1);if(id==='canvasLarger')scale=Math.min(4,scale+.1);if(id==='canvasRotateLeft')rotation-=5;if(id==='canvasRotateRight')rotation+=5;el.dataset.scale=scale;el.dataset.rotation=rotation;el.style.transform=`rotate(${rotation}deg) scale(${scale})`}});

